SELECT R.DIVISION_ID, LEFT(R.YYYYMMDD,6) YM, COUNT(*) N, SUM(CASE WHEN R.QTY = L.QTY THEN 1 ELSE 0 END) KRW_EQ_LOC
FROM DM_PLN_SALES_PLAN_RESULT R WITH(NOLOCK)
JOIN DM_PLN_SALES_PLAN_RESULT L WITH(NOLOCK) ON L.DIVISION_ID=R.DIVISION_ID AND L.PROJECT_CODE=R.PROJECT_CODE AND L.SCM_SITE_ID=R.SCM_SITE_ID AND L.ITEM_ID=R.ITEM_ID AND L.FCST_TYPE=R.FCST_TYPE AND L.DOM_EXP=R.DOM_EXP AND L.INCOTERMS=R.INCOTERMS AND L.PLANT_SITE_ID=R.PLANT_SITE_ID AND L.YYYYMMDD=R.YYYYMMDD AND L.MEASURE='MKT_AMT_LOC'
WHERE R.MEASURE='MKT_AMT_KRW' AND R.YYYYMMDD >= '20260801' AND L.CURRENCY='USD' AND L.QTY<>0 AND R.DIVISION_ID IN ('81','82')
GROUP BY R.DIVISION_ID, LEFT(R.YYYYMMDD,6) ORDER BY 1,2
